<?php
declare(strict_types=1);
$pageUrl = static fn (int $number): string => app_url('/admin/testimonials?' . http_build_query(['q' => $search, 'page' => $number]));
$testimonialRecord ??= null;
$testimonialValues = is_array($testimonialRecord) ? $testimonialRecord : [];
$controlClass = 'mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm';
?>
<div><h1 class="text-3xl font-extrabold text-brand-navy">Testimonials</h1><p class="mt-2 text-slate-600">Only approved testimonials appear on the public homepage.</p></div>
<form class="mt-5 flex gap-2 rounded-2xl border border-slate-200 bg-white p-4" action="<?= e(app_url('/admin/testimonials')) ?>" method="get"><label class="flex-1"><span class="block text-xs font-bold text-slate-600">Search testimonials</span><input class="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" name="q" type="search" maxlength="120" value="<?= e_value($search) ?>"></label><button class="self-end rounded-lg bg-brand-navy px-4 py-2.5 text-sm font-bold text-white">Search</button></form>
<div class="mt-6 grid gap-6 xl:grid-cols-[1fr_1fr]">
  <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
    <?php if ($result['items'] === []): ?><p class="p-8 text-sm text-slate-500">No testimonials found.</p><?php else: ?><ul class="divide-y divide-slate-100"><?php foreach ($result['items'] as $testimonial): ?><li class="flex items-start justify-between gap-4 px-5 py-4"><div><p class="font-bold"><?= e_value($testimonial['customer_display_name']) ?> <span class="text-xs font-normal text-slate-500"><?= $testimonial['rating'] ? '· ' . e_value((string) $testimonial['rating']) . '/5' : '' ?></span></p><p class="mt-1 line-clamp-3 text-sm text-slate-600"><?= e_value($testimonial['quote']) ?></p><p class="mt-2 text-xs text-slate-500"><?= (int) $testimonial['is_approved'] === 1 ? 'Approved' : 'Draft' ?></p></div><a class="shrink-0 text-sm font-bold text-brand-red" href="<?= e(app_url('/admin/testimonials?' . http_build_query(['edit' => (int) $testimonial['id'], 'q' => $search]))) ?>">Edit</a></li><?php endforeach; ?></ul><?php endif; ?>
    <?php if ($result['pages'] > 1): ?><nav class="flex justify-between border-t border-slate-200 px-5 py-3 text-sm"><span>Page <?= e_value((string) $result['page']) ?> / <?= e_value((string) $result['pages']) ?></span><span class="flex gap-3"><?php if ($result['page'] > 1): ?><a class="font-bold text-brand-red" href="<?= e($pageUrl($result['page'] - 1)) ?>">Previous</a><?php endif; ?><?php if ($result['page'] < $result['pages']): ?><a class="font-bold text-brand-red" href="<?= e($pageUrl($result['page'] + 1)) ?>">Next</a><?php endif; ?></span></nav><?php endif; ?>
  </section>
  <section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7">
    <div class="flex items-center justify-between gap-3"><h2 class="text-xl font-extrabold text-brand-navy"><?= $testimonialRecord === null ? 'Add testimonial' : 'Edit testimonial' ?></h2><?php if ($testimonialRecord !== null): ?><a class="text-sm font-bold text-brand-red" href="<?= e(app_url('/admin/testimonials')) ?>">New</a><?php endif; ?></div>
    <form class="mt-5 space-y-4" action="<?= e(app_url('/admin/testimonials/save')) ?>" method="post">
      <input type="hidden" name="_csrf" value="<?= e($csrfToken) ?>"><input type="hidden" name="id" value="<?= e_value((string) ($testimonialValues['id'] ?? '')) ?>">
      <label class="block text-sm font-semibold">Display name<input class="<?= $controlClass ?>" name="customer_display_name" maxlength="160" required value="<?= e_value($testimonialValues['customer_display_name'] ?? '') ?>"></label>
      <label class="block text-sm font-semibold">Quote<textarea class="<?= $controlClass ?> min-h-32" name="quote" maxlength="10000" required><?= e_value($testimonialValues['quote'] ?? '') ?></textarea></label>
      <div class="grid gap-4 sm:grid-cols-2"><label class="block text-sm font-semibold">Rating<select class="<?= $controlClass ?>" name="rating"><option value="">Not supplied</option><?php for ($rating = 1; $rating <= 5; $rating++): ?><option value="<?= $rating ?>"<?= (string) ($testimonialValues['rating'] ?? '') === (string) $rating ? ' selected' : '' ?>><?= $rating ?> / 5</option><?php endfor; ?></select></label><label class="block text-sm font-semibold">Sort order<input class="<?= $controlClass ?>" name="sort_order" type="number" min="0" max="1000000" value="<?= e_value((string) ($testimonialValues['sort_order'] ?? 0)) ?>"></label></div>
      <label class="flex items-center gap-2 text-sm font-semibold"><input name="is_approved" type="checkbox" value="1"<?= (int) ($testimonialValues['is_approved'] ?? 0) === 1 ? ' checked' : '' ?>>Approved for public display</label>
      <button class="rounded-lg bg-brand-red px-4 py-2.5 text-sm font-bold text-white" type="submit"><?= $testimonialRecord === null ? 'Create testimonial' : 'Save testimonial' ?></button>
    </form>
    <?php if ($testimonialRecord !== null): ?><form class="mt-5 border-t border-slate-200 pt-4" action="<?= e(app_url('/admin/testimonials/' . (int) $testimonialRecord['id'] . '/delete')) ?>" method="post"><input type="hidden" name="_csrf" value="<?= e($csrfToken) ?>"><label class="flex gap-2 text-xs text-slate-600"><input class="mt-0.5" type="checkbox" name="confirm_delete" value="1" required><span>I confirm permanently deleting this testimonial.</span></label><button class="mt-3 rounded-lg border border-red-300 px-4 py-2 text-sm font-bold text-red-700" type="submit">Delete</button></form><?php endif; ?>
  </section>
</div>
